import urllib.request
# Try fpbase with full browser headers
headers={'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Accept':'application/json, text/plain, */*','Accept-Language':'en-US,en;q=0.9','Referer':'https://www.fpbase.org/'}
for url in ['https://www.fpbase.org/api/proteins/?name=Clover','https://www.fpbase.org/api/proteins/?name__icontains=clover']:
    try:
        req=urllib.request.Request(url, headers=headers)
        data=urllib.request.urlopen(req, timeout=20).read()
        print(url, 'OK', len(data))
        print(data[:2000].decode(errors='ignore'))
    except Exception as e:
        print(url, 'ERR', e)
        try:
            import urllib.error
            if isinstance(e, urllib.error.HTTPError):
                print(e.read()[:1000])
        except: pass
